  "Decomposing spatial frequencies...",
  "Extracting local phase per sub-band...",
  "Applying Butterworth band-pass filter...",
  "Amplifying phase components...",
  "Reconstructing frames...",
  "Running FFT vibration analysis...",
  "Identifying dominant frequency...",
  "Generating report..."
];

const PRESETS = [
  {
    id: "engine",
    name: "Engine / Motor",
    tag: "10-200 Hz",
    desc: "Rotating machinery"
  },
  {
    id: "structural",
    name: "Structural Flex",
    tag: "0.1-50 Hz",
    desc: "Buildings & bridges"
  },
  {
    id: "custom",
    name: "Custom Range",
    tag: "User-defined",
    desc: "Manual Hz input"
  }
];

const SETTINGS = [
  {
    name: "Amplification Factor",
    hint: "Recommended",
    value: "8x"
  },
  {
    name: "Temporal Filter",
    hint: "Bandpass",
    value: "Ideal BPF"
  },
  {
    name: "Frame Sampling",
    hint: "Auto-detected",
    value: "30 fps"
  },
  {
    name: "Color Map",
    hint: "Displacement",
    value: "Jet (HSV)"
  }
];

function ProcessingOverlay(props) {
  const [step, setStep] = useState(0);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const total = 3800;
    const interval = total / PROCESSING_STEPS.length;

    let elapsed = 0;
    let stepIndex = 0;

    const timer = setInterval(() => {
      elapsed = elapsed + interval;

      const percentage = Math.min(
        (elapsed / total) * 100,
        100
      );

      setProgress(percentage);

      if (stepIndex < PROCESSING_STEPS.length) {
        setStep(stepIndex);
        stepIndex = stepIndex + 1;
      }

      if (elapsed >= total) {
        clearInterval(timer);

        setTimeout(() => {
          if (props.onComplete) {
            props.onComplete();
          }
        }, 400);
      }
    }, interval);

    return () => {
      clearInterval(timer);
    };
  }, [props.onComplete]);

  return (
    <div className="processing-overlay">
      <div className="processing-card">

        <div className="processing-spinner">
          <svg width="56" height="56" viewBox="0 0 56 56">

