                          setMinHz(event.target.value);
                        }}
                      />

                    </div>

                    <div className="custom-input-group">

                      <label>
                        Max Hz
                      </label>

                      <input
                        type="number"
                        placeholder="e.g. 100"
                        value={maxHz}
                        onChange={(event) => {
                          setMaxHz(event.target.value);
                        }}
                      />

                    </div>

                  </div>

                </div>

              )}

            </div>

          </div>

          <div className="sidebar-card">

            <h3 className="sidebar-title">
              Analysis Settings
            </h3>

            <div className="settings-list">

              {SETTINGS.map((setting) => (

                <div
                  key={setting.name}
                  className="setting-row"
                >

                  <div>

                    <span className="setting-name">
                      {setting.name}
                    </span>

                    <span className="setting-hint">
                      {setting.hint}
                    </span>

                  </div>

                  <span className="setting-value">
                    {setting.value}
                  </span>

                </div>

              ))}

            </div>

          </div>

          <button
            className={startButtonClass}
            onClick={startAnalysis}
            disabled={!file || processing}
          >

            {processing && "Processing..."}

            {!processing && file && "Start Analysis"}

            {!processing && !file &&
              "Upload a Video to Continue"}

          </button>

        </div>

      </div>

      {processing && (
        <ProcessingOverlay
          onComplete={() => {
            setProcessing(false);

            if (props.onAnalysisComplete) {
              props.onAnalysisComplete();
            }
          }}
        />
      )}

    </div>
  );
}
